    feature: 'Editor · Image size, status bar',
    goals: ['prepare-for-print', 'make-a-poster'],
    answers: ['how to check image resolution', 'is my image big enough to print', 'how big can i print this photo', 'image resolution checker', 'is my image high resolution', 'what size can i print a photo', 'how to find image pixel size'],
    related: ['image-resolution-explained', 'what-dpi-should-a-poster-be', 'printed-design-looks-blurry', 'fix-a-blurry-image'],
